+                            assert!(in_emulated_range(a, b, c));
+                            assert_eq!(wasm_fma(a, b, c).to_bits(), product.to_bits());
+                            assert_same(a, b, c);
+                            eligible += 1;
+                        }
+                    }
+                }
+            }
+        }
+        assert!(eligible > 64_000);
+        // Outside this range, zero addends retain the existing dispatch.
+        for a in [
