+            f64::MIN_POSITIVE,
+            f64::from_bits(FACTOR_MIN.to_bits() - 1),
+            f64::from_bits(FACTOR_MAX.to_bits() + 1),
+            f64::MAX,
+            f64::INFINITY,
+            f64::NEG_INFINITY,
+            f64::NAN,
+        ] {
+            for c in [0.0, -0.0] {
+                assert!(!in_emulated_range(a, 1.0, c));
+                assert_same(a, 1.0, c);
+                assert_same(1.0, a, c);
+            }
+        }
+    }
